def verdict(case, labels):
    """Return independent failures; permitted positives cannot pass by abstaining."""
    errors = []
    if not case['domains'] <= set(labels.domains): errors.append('missing_domain')
    if case.get('sensitivity') and labels.sensitivity != case['sensitivity']: errors.append('sensitivity')
    if case.get('speech_block') and labels.speech == 'original_message': errors.append('speech')
    if case.get('protection_block') and labels.protected_content == 'none': errors.append('protection')
    would_release = (labels.sensitivity in {'none','personal'} and labels.speech == 'original_message'
                     and labels.protected_content == 'none')
    if would_release != case['release']: errors.append('release')
    return errors
